package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			// PostgreSQL text values cannot contain NUL. Treat this as an invalid
			// target before opening a transaction, as the original action did.
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		result := protocol.Result{ApprovedIDs: append([]string(nil), ids...)}
		requestHash := hashRequest(ids)
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
			return protocol.Result{}, false, err
		}

		// The unique scope key is the serialization point for retries. An
		// already committed row is returned without touching any Purchase row.
		var storedHash string
		var storedResponse []byte
		err = tx.QueryRow(ctx, `
			INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6)
			ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING
			RETURNING "requestHash",response`, u.Tenant, u.User, operation, key, requestHash, response).Scan(&storedHash, &storedResponse)
		if errors.Is(err, pgx.ErrNoRows) {
			if err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse); err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != requestHash {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			var replay protocol.Result
			if err = json.Unmarshal(storedResponse, &replay); err != nil {
				return protocol.Result{}, false, fmt.Errorf("invalid stored action response: %w", err)
			}
			return replay, true, nil
		}
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Lock in canonical ID order. Under READ COMMITTED a waiter sees the
		// committed status from an overlapping transaction and rejects as a
		// whole, leaving its ActionRequest rolled back.
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := 0
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible++
		}
		if err = rows.Err(); err != nil {
			rows.Close()
			return protocol.Result{}, false, err
		}
		rows.Close()
		if eligible != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		for _, id := range ids {
			if _, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus") VALUES ($1,$2,$3,$4,$5,'submitted','approved')`, u.Tenant, id, u.User, operation, key); err != nil {
				return protocol.Result{}, false, err
			}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func hashRequest(ids []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ids {
		_, _ = fmt.Fprintf(h, "%d:%s", len([]byte(id)), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

